-- Expanded pilot catalog: Vegetables, Dairy, Snacks, Drinks (+ more staples).
-- Pattern: shared master items with both vendors at different prices/discounts,
-- plus vendor-unique items. Idempotent-safe for re-seed attempts via NOT EXISTS.

INSERT INTO units (id, code, label)
SELECT 'e3333333-3333-4333-8333-333333333333', 'LITRE', 'Litre'
WHERE NOT EXISTS (SELECT 1 FROM units WHERE id = 'e3333333-3333-4333-8333-333333333333');

INSERT INTO units (id, code, label)
SELECT 'e4444444-4444-4444-8444-444444444444', 'PACK', 'Pack'
WHERE NOT EXISTS (SELECT 1 FROM units WHERE id = 'e4444444-4444-4444-8444-444444444444');

INSERT INTO categories (id, name, description)
SELECT 'd3333333-3333-4333-8333-333333333333', 'Dairy', 'Milk, curd, paneer and more'
WHERE NOT EXISTS (SELECT 1 FROM categories WHERE id = 'd3333333-3333-4333-8333-333333333333');

INSERT INTO categories (id, name, description)
SELECT 'd4444444-4444-4444-8444-444444444444', 'Snacks', 'Biscuits, chips and namkeen'
WHERE NOT EXISTS (SELECT 1 FROM categories WHERE id = 'd4444444-4444-4444-8444-444444444444');

INSERT INTO categories (id, name, description)
SELECT 'd5555555-5555-4555-8555-555555555555', 'Drinks', 'Water, soft drinks, tea and coffee'
WHERE NOT EXISTS (SELECT 1 FROM categories WHERE id = 'd5555555-5555-4555-8555-555555555555');

